+function validateArgs(args) {
+  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
+    throw new Error('Arguments must be an object');
+  }
+  const allowed = ['text', 'mode', 'trim'];
+  for (const key of Object.keys(args)) {
+    if (!allowed.includes(key)) {
+      throw new Error(`Unknown argument: ${key}`);
+    }
+  }
+  if (!('text' in args)) {
+    throw new Error('Missing required argument: text');
+  }
+  if (typeof args.text !== 'string') {
+    throw new Error('Argument "text" must be a string');
+  }
+  if (!('mode' in args)) {
+    throw new Error('Missing required argument: mode');
+  }
+  if (typeof args.mode !== 'string' || !MODES.includes(args.mode)) {
+    throw new Error('Argument "mode" must be one of: uppercase, lowercase, slug');
+  }
+  if ('trim' in args && typeof args.trim !== 'boolean') {
+    throw new Error('Argument "trim" must be a boolean');
+  }
+}
+
+function slugify(text) {
+  return text
+    .toLowerCase()
+    .replace(/[^a-z0-9]+/g, '-')
+    .replace(/^-+|-+$/g, '');
+}
+
+export async function listTools() {
+  return [
+    {
+      name: 'text_transform',
+      description: 'Transform text by uppercasing, lowercasing, or slugifying it.',
+      inputSchema: {
+        type: 'object',
+        properties: {
+          text: { type: 'string', description: 'The text to transform.' },
+          mode: {
+            type: 'string',
+            enum: MODES,
+            description: 'Transform mode: uppercase, lowercase, or slug.'
+          },
+          trim: {
+            type: 'boolean',
+            default: true,
+            description: 'Trim surrounding whitespace before transforming. Defaults to true.'
+          }
+        },
+        required: ['text', 'mode'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'text_transform') {
+    throw new Error(`Unknown tool: ${name}`);
+  }
+  validateArgs(args);
+
+  const { text, mode, trim = true } = args;
+  let out = trim ? text.trim() : text;
+
+  switch (mode) {
+    case 'uppercase':
+      out = out.toUpperCase();
+      break;
+    case 'lowercase':
+      out = out.toLowerCase();
+      break;
+    case 'slug':
+      out = slugify(out);
+      break;
+    default:
+      throw new Error(`Invalid mode: ${mode}`);
+  }
+
+  return { content: [{ type: 'text', text: out }] };
